(480, 'จากภาพแสดงถึงหน้าจอคอมพิวเตอร์ที่มีหลายหน้าต่างเด้งขึ้นมาเกี่ยวข้องกับลักษณะของ Adware ข้อใด', 'data:image/jpeg;base64,', 2, 124);
INSERT INTO `question` (`id`, `content`, `img`, `typeId`, `subjectId`) VALUES
(481, 'จากหน้าเว็บดาวโหลดโปรแกรม ถ้าต้องการดาวโหลดโปรแกรมที่มี Popup โฆษณาปรากฎตามขั้นต้น เพื่อให้สามารถกดปุ่ม Download ได้อย่างปลอดภัยผู้ใช้ควรทำสิ่งใดก่อน?', NULL, 5, 124),
(482, 'จากการทดสอบปฏิบัติการข้อที่ 1 จากการทดสอบปฏิบัติการข้อที่ 1 หากผู้ใช้กดปุ่ม \"Allow\" ที่ popup \"Your Flash Player is out of date\" หรือ \"Claim\" ที่ popup \" You won a prize!\" ผลลัพธ์ที่เป็นไปได้มากที่สุดคืออะไร?', NULL, 3, 124),
(483, 'จากการทดสอบปฏิบัติการข้อที่ 1 ข้อใดคือสัญญาณว่าเว็บไซต์นี้อาจเป็น Adware หรือ Phishing site?', NULL, 6, 124),
(484, 'ข้อใดอธิบายความหมายของ Ransomware ได้ถูกต้องที่สุด?', NULL, 1, 125),
